import{_ as r,a0 as n,w as l,s as o,ao as h,I as p,x as a,a1 as s,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"苹果新的文件系统 APFS 比 HFS+ 强在哪里？ | LCTT x X-CMD","titleTemplate":false,"description":"苹果新的文件系统 APFS 比 HFS+ 强在哪里？ | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"苹果新的文件系统 APFS 比 HFS+ 强在哪里？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"苹果新的文件系统 APFS 比 HFS+ 强在哪里？ | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20161025 What is Apple File System and Why is it Better than HFS","title":"苹果新的文件系统 APFS 比 HFS+ 强在哪里？","tag":"201611","desc":""},"relativePath":"201611/20161025 What is Apple File System and Why is it Better than HFS.md","filePath":"[post].md"}'),d={name:"201611/20161025 What is Apple File System and Why is it Better than HFS.md"};function m(f,e,S,F,c,x){const t=n("Link");return l(),o("div",null,[e[13]||(e[13]=h('<h1 id="苹果新的文件系统-apfs-比-hfs-强在哪里" tabindex="-1">苹果新的文件系统 APFS 比 HFS+ 强在哪里？ <a class="header-anchor" href="#苹果新的文件系统-apfs-比-hfs-强在哪里" aria-label="Permalink to “苹果新的文件系统 APFS 比 HFS+ 强在哪里？”">​</a></h1><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/09/apple-file-system-hero-icon.jpg" alt="" title="What is Apple File System and Why is it Better than HFS+?s"></p><p>如果你一直关注苹果最新版的 macOS 的消息，你可能已经注意到苹果文件系统 APFS。这是不太让人感冒的话题之一。然而，它是支撑了操作系统用户体验的核心结构。APFS 将在 2017 年之前完成，不过你现在可以在 Sierra（最新版的 macOS） 上面体验一番开发者预览版。</p><h3 id="特色与改进" tabindex="-1">特色与改进 <a class="header-anchor" href="#特色与改进" aria-label="Permalink to “特色与改进”">​</a></h3><p>先快速科普一下，<strong>文件系统</strong>是操作系统用于存储和检索数据的基本结构，不同的文件系统采用不同的方式来实现这个任务。随着计算机变得越来越快，新生代的文件系统已经从计算机速度的提升中获益，以提供新功能和适应现代存储需求。</p><p>HFS+，作为今天新一代 Mac 的附带文件系统，已经 18 岁了。它的祖先 HFS 比 Tom Cruise 的兄弟情影片“壮志凌云”还要老。它有点像一辆老丰田。它仍然可以工作（也许惊人的好），但是它不再得到人们的嘉奖。</p><p>APFS 不完全是 HFS+ 的升级版，因为相对现在而言，它是一个大幅度的飞跃。虽然这对苹果用户来说是一个重大的升级，但似乎这看起来更像是苹果赶上了其它系统，而不是超越了它们。然而，更新还进展得非常慢。</p><h3 id="克隆和数据完整性" tabindex="-1">克隆和数据完整性 <a class="header-anchor" href="#克隆和数据完整性" aria-label="Permalink to “克隆和数据完整性”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/apfs-cloning.png" alt="apfs-cloning" title="apfs-cloning"></p><p>APFS 使用称为写时复制（copy-on-write）的方案来生成重复文件的即时克隆。在 HFS+ 下，当用户复制文件的时候，每一个比特（二进制中的“位”）都会被复制。而 APFS 则通过操作元数据并分配磁盘空间来创建克隆。但是，在修改复制的文件之前都不会复制任何比特。当克隆体与原始副本分离的时候，那些改动（并且只有那些改动）才会被保存。</p><p>写时复制还提高了数据的完整性。在其它系统下，如果你卸载卷导致覆写操作挂起的话，你可能会发现你的文件系统有一部分与其它部分不同步。写时复制则通过将改动写入到可用的磁盘空间而不是覆盖旧文件来避免这个问题。直到写入操作成功完成前，旧文件都是正式版本。只有当新文件被成功复制时，旧文件才会被清除。</p><h3 id="系统快照" tabindex="-1">系统快照 <a class="header-anchor" href="#系统快照" aria-label="Permalink to “系统快照”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/apfs-snapshots.png" alt="apfs-snapshots" title="apfs-snapshots"></p><p>快照是写时复制架构给你带来的一个主要的升级。快照是文件系统在某个时间点的一个只读的可装载映像。随着文件系统发生改动，只有改动的比特会被更改。这可以让备份更简单，更可靠。考虑到时间机器（一个苹果出品的备份工具）已经成为硬链接的痛点，这可能是一个重大的升级。</p><h3 id="输入-输出的服务质量-qos" tabindex="-1">输入/输出的服务质量（QoS） <a class="header-anchor" href="#输入-输出的服务质量-qos" aria-label="Permalink to “输入/输出的服务质量（QoS）”">​</a></h3><p>你可能已经在你的路由器说明书看到了服务质量（QoS）这个名词。QoS 优先分配带宽使用以避免降低优先任务的速度。在你的路由器上，它采用用户定义的规则来为指定任务提供最大的带宽。据报道，苹果的 QoS 会优先考虑用户操作，例如活跃窗口。而诸如时间机器备份这些后台任务将会被降级。所以，这意味着更少的闲暇时光了？</p><h3 id="本地加密" tabindex="-1">本地加密 <a class="header-anchor" href="#本地加密" aria-label="Permalink to “本地加密”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/apfs-encryption-1.jpg" alt="apfs-encryption-1" title="apfs-encryption-1"></p><p>在后斯诺登时代，加密成为众所关注的了。越来越多的苹果产品正在强调其系统安全性。内置强大的加密机制并不让人感到意外。包括 APFS 在内，苹果正在采用更加细致入微的加密方案，要么不加密，要么就将加密进行到底。用户可以使用单个密钥来为所有数据加密，或者使用多个加密密钥分别锁定单个文件和文件夹。当然，你也可以不加密，只要你对坏蛋无所忌惮。</p><h3 id="固态硬盘和闪存优化" tabindex="-1">固态硬盘和闪存优化 <a class="header-anchor" href="#固态硬盘和闪存优化" aria-label="Permalink to “固态硬盘和闪存优化”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/apfs-ssd-storage.jpg" alt="apfs-ssd-storage" title="apfs-ssd-storage"></p><p>闪存优化已经被列为 APFS 的一个亮点功能，不过它的实现并没有那么振奋人心。苹果选择将一些典型的固态硬盘芯片的处理功能迁移到操作系统，而没有深度系统集成的优势。这更像是让文件系统感知固态硬盘，而不是为它们做优化。</p><h3 id="动态分区调整" tabindex="-1">动态分区调整 <a class="header-anchor" href="#动态分区调整" aria-label="Permalink to “动态分区调整”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/apfs-partition-resizing.jpg" alt="apfs-partition-resizing" title="apfs-partition-resizing"></p><p>APFS 驱动器的逻辑分区可以动态调整自身大小。用户只需指定所需分区的数量，然后文件系统会在运行时进行磁盘分配。每个分区只占用其用于存储文件的磁盘空间。剩余的磁盘空间会由任何分区获取。这种设计很整洁，不过比起其它文件系统，这更像是元文件夹。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>这是否重要？对于开发者和高级用户来说真是棒极了。对于一般的 Mac 用户应该没有太多的外部差异。虽然升级是重大的举措，但仍然存在一些缺失的部分。本地压缩显然还没有，对用户数据进行的校验也没有。当然，2017 年还没到，一切皆有可能，让我们拭目以待。</p><hr>',28)),p("p",null,[e[1]||(e[1]=a("via: ",-1)),s(t,{href:"https://www.maketecheasier.com/apple-file-system-better-than-hfs/"},{default:i(()=>[...e[0]||(e[0]=[a("https://www.maketecheasier.com/apple-file-system-better-than-hfs/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=a("作者：",-1)),s(t,{href:"https://www.maketecheasier.com/author/alexfox-2-2-2/"},{default:i(()=>[...e[2]||(e[2]=[a("Alexander Fox",-1)])]),_:1}),e[6]||(e[6]=a(" 译者：",-1)),s(t,{href:"https://github.com/OneNewLife"},{default:i(()=>[...e[3]||(e[3]=[a("OneNewLife",-1)])]),_:1}),e[7]||(e[7]=a(" 校对：",-1)),s(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=a("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原创编译，",-1)),s(t,{href:"https://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[a("Linux中国",-1)])]),_:1}),e[12]||(e[12]=a(" 荣誉推出",-1))])])}const u=r(d,[["render",m]]);export{k as __pageData,u as default};
